"""Compile the original zairu.ani panda into the cover's native SpriteFrames."""
import argparse
import json
from pathlib import Path
from tempfile import TemporaryDirectory

from import_assets import ANALYSIS, DEST, bake, parse_ani
from native_ani import native_steps


def frames_resource(info, animation):
    lines = [
        '; Generated by tools/build_cover_panda.py from ssjx/zairu.ani.',
        '; Preserve native layer offsets, transforms, reversed IDs and tick weights.',
        f'[gd_resource type="SpriteFrames" load_steps={info["count"] + 2} format=3]', '',
        f'[ext_resource type="Texture2D" path="{info["texture"]}" id="Atlas"]', '',
    ]
    for i in range(info['count']):
        x = i % info['columns'] * info['width']
        y = i // info['columns'] * info['height']
        lines += [f'[sub_resource type="AtlasTexture" id="Frame_{i}"]',
                  'atlas = ExtResource("Atlas")', 'filter_clip = true',
                  f'region = Rect2({x}, {y}, {info["width"]}, {info["height"]})', '']
    idle = next(i for i, layers in enumerate(animation['frames'])
                if len(layers) == 1 and layers[0]['source'] == 'load00'
                and layers[0]['transform'] == 0)
    clips = [('idle', False, [(idle, 1)])]
    for native_id, name in enumerate(['roll', 'roll_mirrored', 'look_back', 'look_back_mirrored']):
        clips.append((name, native_id < 2, native_steps(animation, native_id)))
    entries = []
    for name, loop, steps in clips:
        frames = ',\n'.join('    {"duration": ' + str(float(ticks))
                            + ', "texture": SubResource("Frame_' + str(frame) + '")}'
                            for frame, ticks in steps)
        entries.append('{\n"frames": [\n' + frames + '\n],\n"loop": '
                       + json.dumps(loop) + ',\n"name": &"' + name + '",\n"speed": 10.0\n}')
    lines += ['[resource]', 'animations = [\n' + ',\n'.join(entries) + '\n]',
              f'metadata/origin = Vector2({info["origin"][0]}, {info["origin"][1]})', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Check generated assets without writing them.')
    args = parser.parse_args()
    animation = parse_ani(ANALYSIS / 'unpacked/ssjx/zairu.ani')
    with TemporaryDirectory(prefix='cover-panda-') as directory:
        info = bake('main/zairu', animation, output_key='cover_panda',
                    texture_dir=directory, texture_prefix='res://assets/ui/')
        files = {'cover_panda.png': (Path(directory) / 'cover_panda.png').read_bytes(),
                 'cover_panda_frames.tres': frames_resource(info, animation).encode('utf-8')}
    stale = []
    for name, content in files.items():
        path = DEST / 'ui' / name
        if path.exists() and path.read_bytes() == content:
            continue
        stale.append(name)
        if not args.check:
            path.write_bytes(content)
    if args.check and stale:
        raise SystemExit('Stale cover panda assets: ' + ', '.join(stale))
    print(f'Cover panda: {info["count"]} original composite frames, 4 native sequences; '
          f'{len(stale)} ' + ('stale' if args.check else 'written'))


if __name__ == '__main__':
    main()
